import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { getPlanLimits } from "@/config/plan-limits";
import {
  RATE_LIMIT_BUCKETS,
  consumeRateLimit,
  getBucketConfig,
  resetRateLimits,
  setOrgPlan,
} from "@/lib/rate-limit";
import { ORG_A, ORG_B } from "../helpers/factories";

beforeEach(() => {
  resetRateLimits();
  vi.useFakeTimers();
  vi.setSystemTime(new Date("2026-03-15T12:00:00.000Z"));
});

afterEach(() => {
  vi.useRealTimers();
});

describe("lib/rate-limit", () => {
  it("returns the declared config for a known bucket", () => {
    expect(getBucketConfig("member:invite")).toEqual(
      RATE_LIMIT_BUCKETS["member:invite"],
    );
  });

  it("falls back to a default config for an unknown bucket", () => {
    const config = getBucketConfig("something:new");
    expect(config.capacity).toBeGreaterThan(0);
    expect(config.refillPerMinute).toBeGreaterThan(0);
  });

  it("allows a first request and reports the remaining tokens", async () => {
    const verdict = await consumeRateLimit(ORG_A, "member:invite");
    expect(verdict.allowed).toBe(true);
    expect(verdict.remaining).toBe(19);
  });

  it("exhausts the bucket and then refuses", async () => {
    const capacity = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < capacity; i += 1) {
      expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(true);
    }

    const denied = await consumeRateLimit(ORG_A, "auth:password-reset");
    expect(denied.allowed).toBe(false);
    expect(denied.remaining).toBe(0);
  });

  it("refills over time at the declared rate", async () => {
    const { capacity, refillPerMinute } = getBucketConfig("auth:password-reset");
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit(ORG_A, "auth:password-reset");
    }
    expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(false);

    vi.advanceTimersByTime(2 * 60_000);
    const after = await consumeRateLimit(ORG_A, "auth:password-reset");
    expect(after.allowed).toBe(true);
    expect(after.remaining).toBe(2 * refillPerMinute - 1);
  });

  it("never refills past capacity", async () => {
    await consumeRateLimit(ORG_A, "member:invite");
    vi.advanceTimersByTime(24 * 60 * 60_000);

    const verdict = await consumeRateLimit(ORG_A, "member:invite");
    expect(verdict.remaining).toBe(getBucketConfig("member:invite").capacity - 1);
  });

  it("charges the supplied cost", async () => {
    const verdict = await consumeRateLimit(ORG_A, "member:invite", 5);
    expect(verdict.allowed).toBe(true);
    expect(verdict.remaining).toBe(15);
  });

  it("refuses a cost larger than the bucket without spending tokens", async () => {
    const denied = await consumeRateLimit(ORG_A, "auth:password-reset", 999);
    expect(denied.allowed).toBe(false);
    expect(denied.remaining).toBe(getBucketConfig("auth:password-reset").capacity);
  });

  it("keeps buckets separate per org and per key", async () => {
    const capacity = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit(ORG_A, "auth:password-reset");
    }

    expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(false);
    expect((await consumeRateLimit(ORG_B, "auth:password-reset")).allowed).toBe(true);
    expect((await consumeRateLimit(ORG_A, "member:invite")).allowed).toBe(true);
  });

  it("scales capacity with the org's plan quota rather than hard-coding it", async () => {
    setOrgPlan(ORG_B, "growth");
    const growth = await consumeRateLimit(ORG_B, "member:invite");
    const free = await consumeRateLimit(ORG_A, "member:invite");

    expect(getPlanLimits("growth").apiRequestsPerHour).toBeGreaterThan(
      getPlanLimits("free").apiRequestsPerHour,
    );
    expect(growth.remaining).toBeGreaterThan(free.remaining);
  });

  it("reports a resetAt in the future when the bucket is empty", async () => {
    const capacity = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit(ORG_A, "auth:password-reset");
    }

    const denied = await consumeRateLimit(ORG_A, "auth:password-reset");
    expect(new Date(denied.resetAt).getTime()).toBeGreaterThan(Date.now());
  });
});

import type {
  EventHandler,
  TaskflowEventMap,
  TaskflowEventPayload,
  TaskflowEventType,
  Unsubscribe,
} from "@/types/event";

/**
 * In-process, typed publish/subscribe bus.
 *
 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
 * every reactive concern `subscribe()`s at module init (see
 * `src/server/services/event-registry.ts`). Handlers are isolated — one
 * throwing handler never fails the emit or the sibling handlers.
 */

type HandlerSet = Set<EventHandler<TaskflowEventType>>;

const handlers = new Map<TaskflowEventType, HandlerSet>();

const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();

/** Registers a handler for one event type. Call the return value to detach. */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const set = handlers.get(type) ?? new Set();
  set.add(handler as EventHandler<TaskflowEventType>);
  handlers.set(type, set);
  return () => {
    set.delete(handler as EventHandler<TaskflowEventType>);
  };
}

/** Registers a handler that detaches itself after the first delivery. */
export function subscribeOnce<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const off = subscribe(type, (payload) => {
    off();
    return handler(payload);
  });
  return off;
}

/**
 * Publishes an event to every subscriber. Resolves once all handlers settle;
 * rejected handlers are reported to the error sinks, never rethrown.
 */
export async function emit<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): Promise<void> {
  const set = handlers.get(type);
  if (!set || set.size === 0) return;

  const results = await Promise.allSettled(
    [...set].map(async (handler) => {
      await (handler as EventHandler<K>)(payload);
    }),
  );

  for (const result of results) {
    if (result.status === "rejected") {
      reportHandlerError(type, result.reason);
    }
  }
}

/** Fire-and-forget variant for call sites that must not await delivery. */
export function emitAndForget<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): void {
  void emit(type, payload).catch((error: unknown) => {
    reportHandlerError(type, error);
  });
}

export function onHandlerError(
  sink: (type: TaskflowEventType, error: unknown) => void,
): Unsubscribe {
  errorSinks.add(sink);
  return () => {
    errorSinks.delete(sink);
  };
}

function reportHandlerError(type: TaskflowEventType, error: unknown): void {
  for (const sink of errorSinks) {
    try {
      sink(type, error);
    } catch {
      // A failing error sink must never escalate.
    }
  }
}

/** Number of live subscribers for an event; used by tests and diagnostics. */
export function subscriberCount(type: TaskflowEventType): number {
  return handlers.get(type)?.size ?? 0;
}

/** Detaches every handler. Test-only — never call from application code. */
export function resetEventBus(): void {
  handlers.clear();
  errorSinks.clear();
}

export type { TaskflowEventMap, TaskflowEventType, Unsubscribe };
